const e=JSON.parse('{"key":"v-fcb98f84","path":"/git/quick-media/photo/","title":"photo-plugin","lang":"zh-CN","frontmatter":{"title":"photo-plugin","order":7,"index":true,"icon":"folder","description":"photo-plugin 是 QuickMedia 系列中负责图片风格化处理的工具包，纯 Java 实现（基于 BufferedImage 逐像素运算，辅以 jhlabs 图像处理库），不依赖任何外部环境，引入依赖即可使用。 它的定位是\\"图片风格化\\"：不是像 imagic-plugin 那样做旋转、裁剪这类几何编辑，而是给图片\\"换一种画风\\"——比如把一张照片变成手绘素描，或者把照片变成一张线稿。这类操作的实现原理多是图像处理中经典的滤波、卷积和混合算法，photo-plugin 把它们封装成了统一的算子（Operator）模型：每个算子对外暴露相同的用法（of 指定算子 → setImg 传图 → 链式配置参数 → asImg/asFile 输出），上手成本很低。","head":[["meta",{"property":"og:url","content":"https://liuyueyi.github.io/tutorial/git/quick-media/photo/"}],["meta",{"property":"og:site_name","content":"一灰灰的站点"}],["meta",{"property":"og:title","content":"photo-plugin"}],["meta",{"property":"og:description","content":"photo-plugin 是 QuickMedia 系列中负责图片风格化处理的工具包，纯 Java 实现（基于 BufferedImage 逐像素运算，辅以 jhlabs 图像处理库），不依赖任何外部环境，引入依赖即可使用。 它的定位是\\"图片风格化\\"：不是像 imagic-plugin 那样做旋转、裁剪这类几何编辑，而是给图片\\"换一种画风\\"——比如把一张照片变成手绘素描，或者把照片变成一张线稿。这类操作的实现原理多是图像处理中经典的滤波、卷积和混合算法，photo-plugin 把它们封装成了统一的算子（Operator）模型：每个算子对外暴露相同的用法（of 指定算子 → setImg 传图 → 链式配置参数 → asImg/asFile 输出），上手成本很低。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-11-13T01:09:18.000Z"}],["meta",{"property":"article:modified_time","content":"2026-11-13T01:09:18.000Z"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"photo-plugin\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2026-11-13T01:09:18.000Z\\",\\"author\\":[]}"]]},"headers":[],"git":{"createdTime":1675325046000,"updatedTime":1794532158000,"contributors":[{"name":"YiHui","email":"bangzewu@126.com","commits":1},{"name":"yihui","email":"bangzewu@126.com","commits":1}]},"readingTime":{"minutes":1.56,"words":468},"filePathRelative":"git/quick-media/photo/README.md","localizedDate":"2023年2月2日","excerpt":"<p>photo-plugin 是 QuickMedia 系列中负责图片风格化处理的工具包，<strong>纯 Java 实现</strong>（基于 BufferedImage 逐像素运算，辅以 jhlabs 图像处理库），不依赖任何外部环境，引入依赖即可使用。</p>\\n<p>它的定位是\\"图片风格化\\"：不是像 imagic-plugin 那样做旋转、裁剪这类几何编辑，而是给图片\\"换一种画风\\"——比如把一张照片变成手绘素描，或者把照片变成一张线稿。这类操作的实现原理多是图像处理中经典的滤波、卷积和混合算法，photo-plugin 把它们封装成了统一的算子（Operator）模型：每个算子对外暴露相同的用法（<code>of</code> 指定算子 → <code>setImg</code> 传图 → 链式配置参数 → <code>asImg</code>/<code>asFile</code> 输出），上手成本很低。</p>","copyright":{},"autoDesc":true}');export{e as data};
